with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, '聖マタイの召命', 'カラヴァッジョ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Caravaggio_%E2%80%94_The_Calling_of_Saint_Matthew.jpg/960px-Caravaggio_%E2%80%94_The_Calling_of_Saint_Matthew.jpg', '1599〜1600年ごろ、ローマのサン・ルイジ・デイ・フランチェージ聖堂コンタレッリ礼拝堂のために描かれた大作で、今も同じ礼拝堂に掛かっています。収税人マタイが、イエスに呼ばれて弟子になる場面です。薄暗い部屋で当時の服を着た男たちがお金を数えるところへ、右から差し込む光とともにイエスが指をさします。マタイが中央のひげの男か、左端でうつむく若者かは、今も議論が分かれています。カラヴァッジョの公の場でのデビュー作で、バロック絵画への道を開いた作品とされます。', 'CC0', null, 'https://commons.wikimedia.org/wiki/File:Caravaggio_—_The_Calling_of_Saint_Matthew.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 1
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('MOA美術館、国宝3件を同時公開へ', 'リニューアル10周年記念名品展で、光琳の国宝「紅白梅図屏風」など館蔵の国宝3件を2027年1月9日から同時公開。', '静岡県熱海市のMOA美術館は、2027年1月9日から2月24日まで「リニューアル10周年記念名品展 国宝「紅白梅図屏風」」を開催します。過去10年の代表的な展覧会を振り返りながら、創立者・岡田茂吉のコレクションから日本美術を厳選して展示します。中心となるのは館蔵の国宝3件の同時公開で、尾形光琳の晩年の作と考えられる「紅白梅図屏風」、野々村仁清「色絵藤花文茶壺」、311葉の古筆切を収めた手鑑「翰墨城」が並びます。酒井抱一「雪月花図」なども出品され、隣接する梅園の見ごろに合わせた企画です。', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Ogata_K%C5%8Drin_-_Red_and_White_Plum_Blossoms.jpg/960px-Ogata_K%C5%8Drin_-_Red_and_White_Plum_Blossoms.jpg', '展覧会', 'https://artexhibition.jp/topics/news/20261027-AEJ3028799/',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Ogata_Kōrin_-_Red_and_White_Plum_Blossoms.jpg')
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('デュフィ展、2027年春に東京都美術館で', '生誕150周年を記念する回顧展。幅6メートルの《電気の精》が来日し、京都市京セラ美術館に巡回する。', 'フランスの画家ラウル・デュフィ（1877〜1953）の生誕150周年を記念する「デュフィ展」が、2027年4月24日から8月22日まで東京都美術館で開かれます。パリ市立近代美術館を中心に国内外のコレクションから約120点を集め、絵画のほかテキスタイル、衣装、陶器、タペストリー、家具も紹介します。1937年パリ万国博覧会の「電気と光のパビリオン」の大壁画の構想過程で描かれた幅6メートルの油彩画《電気の精》が来日し、準備段階の素描も展示されます。その後、京都市京セラ美術館に巡回し、9月11日から12月12日まで開かれます。', '', '展覧会', 'https://artexhibition.jp/topics/news/20261112-AEJ3039273/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('福田美術館、2027年の4展を発表', '現代アートと江戸絵画の共演、江戸琳派、大観・若冲の大作、動物画の4展。木島櫻谷の幻の文展出品作も公開。', '京都市右京区の福田美術館が、2027年の展覧会スケジュールを発表しました。1月30日からの「Timeless Code 現代⇔江戸」では、草間彌生や奈良美智らの現代アートと、伊藤若冲や円山応挙らの江戸絵画を並べて見せます。6月19日からの「りん・りん・琳派」は、2026年に収蔵した江戸琳派の作品約20点を中心に琳派の系譜をたどります。9月11日からの「オールスター名画祭（仮）」では、横山大観《富士図》や若冲の全長約11mの《果蔬図巻》が登場し、最近発見された木島櫻谷の文展出品作《孟宗藪》が110年ぶりに公開されます。', '', '美術館', 'https://artexhibition.jp/topics/news/20261110-AEJ3038098/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('【特集】2026年 日展の見どころ', '第119回日展が国立新美術館で11月22日まで。日本画・洋画・彫刻・工芸美術・書の5部門、約3,000点が並ぶ。', '第119回日展が、2026年10月30日から11月22日まで東京・六本木の国立新美術館で開かれています。日展は、日本画・洋画・彫刻・工芸美術・書の五つの部門からなる総合美術展で、会場には約3,000点の作品が並びます。休館日は11月17日（火）、観覧時間は午前10時から午後6時（入場は午後5時30分まで）で、当日券は一般1,500円、午後4時からのトワイライトチケットは700円です。高校生・大学生と中学生以下は無料です。東京展の後は、京都市京セラ美術館（12月19日〜2027年1月16日）、名古屋、大阪、富山を巡回する予定です。', '', '特集', 'https://nitten.or.jp/summary',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('黄・赤・青', 'Yellow-Red-Blue', 'ワシリー・カンディンスキー', 'Wassily Kandinsky',
        1925,
        (select slug from public.art_movements where slug = 'expressionism'),
        'ポンピドゥー・センター（国立近代美術館）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Kandinsky_-_Jaune_Rouge_Bleu.jpg/960px-Kandinsky_-_Jaune_Rouge_Bleu.jpg', 'カンディンスキーがバウハウスで教えていた1925年に、ヴァイマルで描いた油彩画で、横幅は約2メートルあります。黄色を中心とした左側と、大きな青い円が置かれた右側が向き合い、円や直線、格子などの形が音楽の和音のように響き合います。青騎士の時代には色の渦が画面を満たしていましたが、バウハウスの時期には、円や直線、三角形といったはっきりした幾何学的な形で画面を組み立てるようになりました。内面を表すという表現主義の考えを受け継ぎながら、それを形と色の理論へと整理していった時期の作品です。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Kandinsky_-_Jaune_Rouge_Bleu.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('ドーヴィルの浜辺', 'The Beach at Deauville', 'ウジェーヌ・ブーダン', 'Eugène Boudin',
        1864,
        (select slug from public.art_movements where slug = 'impressionism'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1946.71/1946.71_web.jpg', 'ノルマンディーの海辺の保養地ドーヴィルの浜辺を、板に油彩で描いた1864年の作品です。ブーダンはトルーヴィルやドーヴィルの浜辺を、広い空とともにくり返し描きました。画面の多くを占める空と、低い位置に小さく並ぶ人々の対比が見どころで、雲や風の動きまで感じさせます。その空の描写から、ボードレールやコローに「空の王者」とたたえられました。ブーダンは若いモネに屋外で絵を描くことを教え、1874年の第1回印象派展にも参加しています。屋外で光と大気をとらえる姿勢は、印象派へと受け継がれました。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1946.71')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('ウルビーノのヴィーナス', 'Venus of Urbino', 'ティツィアーノ・ヴェチェッリオ', 'Titian',
        1538,
        (select slug from public.art_movements where slug = 'renaissance'),
        'ウフィツィ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Tiziano%27s_Venere_di_Urbino_%28from_The_History_BLog%29.jpg/960px-Tiziano%27s_Venere_di_Urbino_%28from_The_History_BLog%29.jpg', '1538年ごろ、ウルビーノ公グイドバルド2世・デッラ・ローヴェレのために描かれた油彩画です。寝台に横たわる裸婦が見る人のほうを向き、足もとでは小犬が眠り、奥では侍女が衣装箱の中を探っています。ポーズはジョルジョーネの《眠れるヴィーナス》にならったものとされますが、ティツィアーノは女神を宮殿の室内に移し、目を開いた姿にして、より官能的な像にしました。ヴェネツィア派らしい柔らかな色と肌の表現も見どころです。この図像は、19世紀にマネが《オランピア》で娼婦の姿に描き直したことでも知られます。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Tiziano''s_Venere_di_Urbino_(from_The_History_BLog).jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('松島図屏風', 'Waves at Matsushima', '俵屋宗達', 'Tawaraya Sōtatsu',
        null,
        (select slug from public.art_movements where slug = 'rinpa'),
        'フリーア美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/%E4%BF%B5%E5%B1%8B%E5%AE%97%E9%81%94%E3%80%8A%E6%9D%BE%E5%B3%B6%E5%9B%B3%E3%80%8B17%E4%B8%96%E7%B4%80%E3%80%81%E3%83%95%E3%83%AA%E3%83%BC%E3%82%A2%E7%BE%8E%E8%A1%93%E9%A4%A82.jpg/960px-%E4%BF%B5%E5%B1%8B%E5%AE%97%E9%81%94%E3%80%8A%E6%9D%BE%E5%B3%B6%E5%9B%B3%E3%80%8B17%E4%B8%96%E7%B4%80%E3%80%81%E3%83%95%E3%83%AA%E3%83%BC%E3%82%A2%E7%BE%8E%E8%A1%93%E9%A4%A82.jpg', '1620年代ごろに描かれたとされる六曲一双の屏風で、紙に墨、色、金、銀で描かれています。松の生えた岩を荒い波が取り巻き、白と金の線を重ねた波が画面いっぱいにうねります。雲や州浜は金箔で表され、銀は年月とともに黒く変わっています。絵の具が乾ききらないうちに別の色を垂らしてにじませる「たらし込み」の技法も使われています。1906年にチャールズ・ラング・フリーアが買い求め、アメリカに渡りました。のちに尾形光琳がこの作品をもとに屏風を描き、宗達に始まる琳派の流れを示す作品です。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:俵屋宗達《松島図》17世紀、フリーア美術館2.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ウジェーヌ・ブーダン', 'Eugène Boudin', 'ブーダン',
        1824, 1898, 'west', array['impressionism']::text[],
        'ノルマンディーの浜辺と空を描き、「印象派の先駆者」と呼ばれるフランスの画家。', '1824年、ノルマンディーの港町オンフルールに船乗りの子として生まれました。1835年に家族とル・アーヴルに移り、そこでトロワイヨンやミレーらバルビゾン派の画家と知り合いました。

1857年に若いモネと出会い、屋外で絵を描くことを教えました。1859年にはクールベと知り合い、のちにボードレールを紹介されています。トルーヴィルやドーヴィルの浜辺、ル・アーヴルの港を、広い空とともにくり返し描き、ボードレールやコローから「空の王者」とたたえられました。

1874年の第1回印象派展に参加し、1892年にはレジオンドヌール勲章を受けました。1898年にドーヴィルで亡くなりました。屋外で光と大気をとらえる姿勢は、モネを通じて印象派に受け継がれました。', 'https://ja.wikipedia.org/wiki/%E3%82%A6%E3%82%B8%E3%82%A7%E3%83%BC%E3%83%8C%E3%83%BB%E3%83%96%E3%83%BC%E3%83%80%E3%83%B3')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('ラウル・デュフィ', 'Raoul Dufy', 'デュフィ',
        1877, 1953, 'west', array['fauvism']::text[],
        '明るく透明な色とリズミカルな線で、海や競馬、音楽を描いたフランスの画家。', '1877年、フランスの港町ル・アーヴルに生まれました。1895年から地元の市立美術学校の夜間クラスに通い、1900年に奨学金を得てパリの国立美術学校に入りました。同級生にジョルジュ・ブラックがいます。

マティスの影響を受けてフォーヴィスムの画家として出発し、1908年ごろにはセザンヌの影響を受けた描き方に移りました。やがて明るく透明な色と軽やかな線で、海辺や競馬、音楽を主題とする独自の画風を確立しました。1911年にはポール・ポワレと木版プリントの布地をつくり、翌年からはリヨンの絹織物会社とデザイナー契約を結ぶなど、本の挿絵や舞台美術、テキスタイルでも活躍しました。

1937年のパリ万国博覧会では、長さ約60メートルの大壁画《電気の精》を手がけました。1953年に南フランスのフォルカルキエで亡くなりました。', 'https://ja.wikipedia.org/wiki/%E3%83%A9%E3%82%A6%E3%83%AB%E3%83%BB%E3%83%87%E3%83%A5%E3%83%95%E3%82%A3')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
